import sys

lines = sys.stdin.read().split('\n')
n = int(lines[0])
pending = {}
out = []
for i in range(1, n + 1):
    p = lines[i].split()
    if p[0] == 'schedule':
        pending[p[1]] = int(p[2])
    else:
        now = int(p[1])
        due = sorted((t, e) for e, t in pending.items() if t <= now)
        for t, e in due:
            del pending[e]
        out.append(' '.join(e for t, e in due) if due else 'none')
print('\n'.join(out))

