def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    tests = [
        fmt(['poll 0']),
        fmt(['schedule a 0', 'poll 0']),
        fmt(['schedule a 5', 'schedule a 5', 'poll 5', 'poll 5']),
        fmt(['schedule b 7', 'schedule a 7', 'schedule c 7', 'poll 7']),
        fmt(['schedule a 5', 'schedule a 9', 'poll 6', 'poll 9', 'schedule a 5', 'poll 5']),
        fmt(['schedule a 5', 'poll 10', 'schedule a 20', 'poll 15', 'poll 25']),
        fmt(['schedule z9 1000000000', 'poll 999999999', 'poll 1000000000']),
        fmt(['schedule a1 3', 'schedule a 3', 'schedule a10 3', 'poll 3']),
    ]
    for _ in range(60):
        pool = ['a', 'b', 'c', 'd', 'e', 'f1', 'f10'][:rng.randint(2, 7)]
        ops = []
        for _ in range(rng.randint(2, 28)):
            if rng.random() < 0.55:
                ops.append(f"schedule {rng.choice(pool)} {rng.randint(0, 20)}")
            else:
                ops.append(f"poll {rng.randint(0, 25)}")
        if not any(o.startswith('poll') for o in ops):
            ops.append('poll 25')
        tests.append(fmt(ops))

    def big(n, pool_size, poll_ratio, mode):
        ops = []
        for i in range(n):
            if rng.random() < poll_ratio:
                if mode == 'inc':
                    ops.append(f"poll {int(i / n * 10**9)}")
                else:
                    ops.append(f"poll {rng.randint(0, 10**9)}")
            else:
                ops.append(f"schedule e{rng.randrange(pool_size)} {rng.randint(0, 10**9)}")
        ops.append('poll 1000000000')
        return fmt(ops[:n - 1] + ['poll 1000000000'])

    tests.append(big(100000, 20000, 0.5, 'inc'))
    tests.append(big(100000, 20000, 0.5, 'rand'))
    # many schedules first, then slowly advancing polls
    ops = [f"schedule e{rng.randrange(30000)} {rng.randint(0, 10**9)}" for _ in range(50000)]
    ops += [f"poll {i * 20000}" for i in range(1, 50001)]
    tests.append(fmt(ops))
    # everything due at once
    ops = [f"schedule e{i} 777" for i in range(30000)] + ['poll 776', 'poll 777', 'poll 778']
    tests.append(fmt(ops))
    return tests

